<div class="page-head"><div><h1>Notifications</h1><p>Audit trail of score, validation, event, team, and account changes.</p></div></div><section class="panel notification-list"><?php foreach($notifications as $n): ?><div class="notification-row"><span class="notice-dot" aria-hidden="true"><?= ui_icon('bell') ?></span><div><b><?= esc($n['actor_name']??'System') ?></b><p><?= esc($n['message']) ?></p><small><?= esc(date('M j, Y · g:i A',strtotime($n['created_at']))) ?> · <?= esc(str_replace('_',' ',$n['action'])) ?></small></div></div><?php endforeach; ?><?php if (empty($notifications)): ?><div class="empty">No notifications yet.</div><?php endif; ?></section>
